def count_pairs(nums, target):
    lo, hi = 0, len(nums) - 1
    count = 0
    while lo < hi:
        s = nums[lo] + nums[hi]
        if s < target:
            lo += 1
        elif s > target:
            hi -= 1
        elif nums[lo] == nums[hi]:
            k = hi - lo + 1
            count += k * (k - 1) // 2
            break
        else:
            a = 1
            while nums[lo + a] == nums[lo]:
                a += 1
            b = 1
            while nums[hi - b] == nums[hi]:
                b += 1
            count += a * b
            lo, hi = lo + a, hi - b
    return count

