static long countPairs(int[] nums, long target) {
    int lo = 0, hi = nums.length - 1;
    long count = 0;
    while (lo < hi) {
        long s = (long) nums[lo] + nums[hi];
        if (s < target) lo++;
        else if (s > target) hi--;
        else if (nums[lo] == nums[hi]) {
            long k = hi - lo + 1;
            count += k * (k - 1) / 2;
            break;
        } else {
            int a = 1, b = 1;
            while (nums[lo + a] == nums[lo]) a++;
            while (nums[hi - b] == nums[hi]) b++;
            count += (long) a * b;
            lo += a;
            hi -= b;
        }
    }
    return count;
}

