def best_under(prices, cap):
    lo, hi = 0, len(prices) - 1
    best = -1
    while lo < hi:
        s = prices[lo] + prices[hi]
        if s <= cap:
            best = max(best, s)
            lo += 1
        else:
            hi -= 1
    return best

code.java:
static long bestUnder(int[] prices, long cap) {
    int lo = 0, hi = prices.length - 1;
    long best = -1;
    while (lo < hi) {
        long s = (long) prices[lo] + prices[hi];
        if (s <= cap) {
            best = Math.max(best, s);
            lo++;
        } else {
            hi--;
        }
    }
    return best;
}

