def is_palindrome(word):
    lo, hi = 0, len(word) - 1
    while lo < hi:
        if word[lo] != word[hi]:
            return False
        lo, hi = lo + 1, hi - 1
    return True

code.java:
static boolean isPalindrome(String word) {
    int lo = 0, hi = word.length() - 1;
    while (lo < hi) {
        if (word.charAt(lo) != word.charAt(hi))
            return false;
        lo++;
        hi--;
    }
    return true;
}

